import { all, read, currentUser } from '../utils/storage.js';
import { escapeHTML as e, money, shortDate, dateTime, initials, statusPill, safeImage, today } from '../utils/helpers.js';
import { farmerProfileFor, requestRental } from './rentals.js';
import { getCart } from './cart.js';
import { expensesFor, expenseTotals } from './expenses.js';

const IMG = '../agriculture-platform/images/';
const link = (href, label, active, key) => `<a class="p2-nav-link ${active === key ? 'is-current' : ''}" href="${href}">${label}</a>`;

function sidebar(user, page) {
  const admin = user.role === 'admin';
  const nav = admin
    ? [['dashboard','Overview','dashboard'],['farmers','Farmer records','farmers'],['crops','Crop library','crops'],['equipment','Equipment','equipment'],['rental','Rental requests','rental'],['products','Products','products'],['orders','Orders','orders'],['reports','Reports','reports']]
    : [['dashboard','My dashboard','dashboard'],['crops','Explore crops','crops'],['equipment','Rent equipment','equipment'],['rental','My rentals','rental'],['products','Farm supplies','products'],['cart','Shopping cart','cart'],['orders','My orders','orders'],['expenses','Expense calculator','expenses']];
  return `<aside class="p2-sidebar">
    <a class="p2-brand" href="../index.html"><img src="${IMG}logo/logo-mark.svg" alt=""><span><strong>Kisan Mitra</strong><small>Farm management</small></span></a>
    <div class="p2-sidebar-section">${admin ? 'ADMIN CONSOLE' : 'FARMER WORKSPACE'}</div>
    <nav class="p2-nav" aria-label="Main navigation">${nav.map(([key,label]) => link(`${key}.html`,label,page,key)).join('')}</nav>
    <div class="p2-sidebar-bottom"><div class="p2-sidebar-tip"><strong>Good farming starts with good planning.</strong><span>Keep your records updated for a clearer view of the season.</span></div><a href="information.html" class="p2-nav-link ${page==='information'?'is-current':''}">Agriculture information</a><a href="contact.html" class="p2-nav-link ${page==='contact'?'is-current':''}">Help &amp; contact</a></div>
  </aside>`;
}

function mobileNav(user, page) {
  const nav = user.role === 'admin'
    ? [['dashboard','Dashboard'],['farmers','Farmers'],['crops','Crops'],['equipment','Equipment'],['rental','Rentals'],['products','Products'],['orders','Orders'],['reports','Reports']]
    : [['dashboard','Dashboard'],['crops','Crops'],['equipment','Equipment'],['rental','Rentals'],['products','Products'],['cart','Cart'],['orders','Orders'],['expenses','Expenses']];
  return `<nav class="p2-mobile-nav" aria-label="Mobile navigation">${nav.map(([key,label])=>`<a class="${page===key?'is-current':''}" href="${key}.html">${label}</a>`).join('')}</nav>`;
}

function topbar(user) {
  return `<header class="p2-topbar"><div class="p2-topbar-title"><span class="p2-mobile-brand">Kisan Mitra</span><span class="p2-role-label">${user.role === 'admin' ? 'ADMIN WORKSPACE' : 'FARMER WORKSPACE'}</span></div><div class="p2-topbar-tools"><label class="p2-global-search"><span aria-hidden="true">⌕</span><input id="global-search" type="search" placeholder="Search crops or products" aria-label="Search crops or products"></label><button class="icon-button" type="button" data-action="theme-toggle" aria-label="Toggle dark or light mode" title="Toggle theme">◐</button><div class="p2-user-chip"><span class="p2-avatar">${e(initials(user.name))}</span><span><strong>${e(user.name)}</strong><small>${user.role === 'admin' ? 'Administrator' : 'Farmer'}</small></span></div><button class="btn btn-secondary btn-sm" type="button" data-action="logout">Sign out</button></div></header>`;
}

export function renderShell(user, page, content) {
  document.getElementById('app').innerHTML = `<div class="p2-app">${sidebar(user,page)}<div class="p2-main">${topbar(user)}${mobileNav(user,page)}<main class="p2-content" id="main">${content}</main></div></div><div id="toast-region" class="toast-region" aria-live="polite"></div>`;
}

function pageHeader(title, subtitle, actions = '') {
  return `<div class="page-header p2-page-header"><div><div class="p2-eyebrow">KISAN MITRA / PHASE 2</div><h1 class="page-header__title">${title}</h1><p class="page-header__subtitle">${subtitle}</p></div><div class="page-header__actions">${actions}</div></div>`;
}

function statCard(label, value, note, symbol = '↗', tone = '') {
  return `<article class="stats-card p2-stat-card"><div class="stats-card__icon ${tone}">${symbol}</div><div class="stats-card__content"><div class="stats-card__label">${label}</div><div class="stats-card__value">${value}</div><div class="stats-card__note">${note}</div></div></article>`;
}

function emptyState(title, text, action = '') {
  return `<div class="p2-empty"><div class="p2-empty-icon">✳</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
}

function tableCard(title, description, headers, rows, footer = '') {
  return `<section class="card p2-card"><div class="card__header"><div><h2 class="card__title">${title}</h2><p class="text-small">${description}</p></div></div><div class="card__body card__body--flush"><div class="table-wrap"><table class="table"><thead><tr>${headers.map((h) => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows || `<tr><td colspan="${headers.length}">${emptyState('Nothing here yet','Records will appear here as soon as they are added.')}</td></tr>`}</tbody></table></div></div>${footer ? `<div class="card__footer">${footer}</div>` : ''}</section>`;
}

function dashboard(user) {
  const farmers = all('farmers'); const crops = all('crops'); const equipment = all('equipment'); const products = all('products');
  const rentals = all('rentals'); const orders = all('orders'); const activities = all('activity');
  const admin = user.role === 'admin';
  if (admin) {
    const pendingOrders = orders.filter((o) => o.status === 'Pending').length;
    const rented = equipment.filter((item) => item.status === 'Rented').length;
    const stats = `<div class="grid grid--4 p2-stats">
      ${statCard('Total farmers', farmers.length, `${farmers.filter(f=>f.status==='Active').length} active profiles`, '♙')}
      ${statCard('Crop records', crops.length, `${new Set(crops.map(c=>c.category)).size} crop categories`, '♧','stats-card__icon--secondary')}
      ${statCard('Equipment available', equipment.filter(x=>x.status==='Available').length, `${rented} currently rented`, '⚙','stats-card__icon--info')}
      ${statCard('Products listed', products.length, `${products.reduce((s,p)=>s+Number(p.stock||0),0)} total stock units`, '▣','stats-card__icon--accent')}
      ${statCard('Total orders', orders.length, `${pendingOrders} pending`, '🛒')}
      ${statCard('Rental requests', rentals.length, `${rentals.filter(r=>r.status==='Pending').length} awaiting review`, '↗','stats-card__icon--secondary')}
      ${statCard('Completed orders', orders.filter(o=>o.status==='Delivered').length, 'Successfully delivered', '✓','stats-card__icon--info')}
      ${statCard('Rental activity', rentals.filter(r=>['Approved','Active'].includes(r.status)).length, 'Approved or active rentals', '◷','stats-card__icon--accent')}
    </div>`;
    const farmerRows = farmers.slice(0,5).map(f=>`<tr><td><div class="p2-person"><img src="${safeImage(f.image)}" alt=""><span><strong>${e(f.name)}</strong><small>${e(f.email)}</small></span></div></td><td>${e(f.village || '—')}</td><td>${e(f.district || '—')}</td><td>${statusPill(f.status)}</td></tr>`).join('');
    const activityRows = activities.slice(0,6).map(a=>`<div class="p2-activity"><span class="p2-activity-dot"></span><div><strong>${e(a.message)}</strong><small>${dateTime(a.createdAt)}</small></div></div>`).join('') || emptyState('No activity yet','New actions will be listed here.');
    const pendingRows = [...rentals.filter(r=>r.status==='Pending').slice(0,3).map(r=>({kind:'Rental',name:r.equipmentName,who:r.farmerName,status:r.status})),...orders.filter(o=>o.status==='Pending').slice(0,3).map(o=>({kind:'Order',name:o.id,who:o.farmerName,status:o.status}))].slice(0,5).map(item=>`<tr><td>${item.kind}</td><td><strong>${e(item.name)}</strong><small class="p2-subcell">${e(item.who)}</small></td><td>${statusPill(item.status)}</td></tr>`).join('');
    return `${pageHeader('Admin dashboard','A live summary of farmers, crops, equipment, rentals and farm supply orders.',`<a class="btn btn-primary" href="farmers.html?action=create">＋ Add farmer</a>`)}${stats}<div class="grid grid--2 p2-dashboard-grid">${tableCard('Recent farmers','Latest farmer profiles',['Farmer','Village','District','Status'],farmerRows,`<a class="btn-link" href="farmers.html">View all farmers →</a>`)}${tableCard('Needs your attention','Pending rental and order requests',['Type','Record','Status'],pendingRows,`<a class="btn-link" href="rental.html">Review requests →</a>`)}</div><div class="grid grid--2 p2-dashboard-grid"><section class="card p2-card"><div class="card__header"><h2 class="card__title">Recent activity</h2></div><div class="card__body">${activityRows}</div></section><section class="card p2-card"><div class="card__header"><h2 class="card__title">Quick actions</h2></div><div class="card__body p2-quick-grid"><a href="farmers.html?action=create">＋ Add farmer</a><a href="crops.html?action=create">＋ Add crop</a><a href="equipment.html?action=create">＋ Add equipment</a><a href="products.html?action=create">＋ Add product</a><a href="orders.html">▤ Manage orders</a><a href="reports.html">▥ Open reports</a></div></section></div>`;
  }
  const profile = farmerProfileFor(user); const ownerId = profile?.id || user.farmerId || user.id;
  const myOrders = orders.filter(o=>o.farmerId===ownerId); const myRentals = rentals.filter(r=>r.farmerId===ownerId); const myExpenses = expensesFor(user);
  const stats = `<div class="grid grid--4 p2-stats">${statCard('My orders',myOrders.length,`${myOrders.filter(o=>o.status==='Pending').length} awaiting confirmation`,'🛒')}${statCard('Delivered orders',myOrders.filter(o=>o.status==='Delivered').length,'Completed supply orders','✓','stats-card__icon--secondary')}${statCard('Active rentals',myRentals.filter(r=>['Approved','Active'].includes(r.status)).length,'Approved equipment rentals','⚙','stats-card__icon--info')}${statCard('Farm expenses',money(expenseTotals(myExpenses)),'Recorded expenses so far','₹','stats-card__icon--accent')}</div>`;
  const myOrderRows = myOrders.slice(0,5).map(o=>`<tr><td><strong>${e(o.id)}</strong><small class="p2-subcell">${shortDate(o.createdAt)}</small></td><td>${o.items.length} item(s)</td><td>${money(o.total)}</td><td>${statusPill(o.status)}</td></tr>`).join('');
  const rentalRows = myRentals.slice(0,5).map(r=>`<tr><td>${e(r.equipmentName)}</td><td>${shortDate(r.startDate)} – ${shortDate(r.endDate)}</td><td>${money(r.amount)}</td><td>${statusPill(r.status)}</td></tr>`).join('');
  return `${pageHeader(`Welcome, ${e(user.name.split(' ')[0])}`,'Your farm services, recent orders and rental activity at a glance.',`<a class="btn btn-primary" href="products.html">Browse farm supplies</a>`)}${stats}<div class="grid grid--2 p2-dashboard-grid">${tableCard('Recent orders','Your latest product orders',['Order','Items','Total','Status'],myOrderRows,`<a class="btn-link" href="orders.html">View all orders →</a>`)}${tableCard('Equipment rentals','Your recent equipment requests',['Equipment','Rental period','Charge','Status'],rentalRows,`<a class="btn-link" href="rental.html">View rental history →</a>`)}</div><div class="grid grid--2 p2-dashboard-grid"><section class="card p2-card"><div class="card__header"><h2 class="card__title">Quick services</h2></div><div class="card__body p2-quick-grid"><a href="crops.html">♧ Explore crop information</a><a href="equipment.html">⚙ Find farm equipment</a><a href="products.html">▣ Order farm supplies</a><a href="expenses.html">₹ Calculate farm expenses</a></div></section><section class="card p2-card"><div class="card__header"><h2 class="card__title">My profile</h2><a class="btn-link" href="farmers.html">Profile details</a></div><div class="card__body"><div class="p2-profile"><span class="p2-avatar p2-avatar-large">${e(initials(user.name))}</span><div><strong>${e(user.name)}</strong><p>${e(profile?.village || 'Village not added')}, ${e(profile?.district || 'District not added')}</p><small>${e(user.email)}</small></div></div><p class="form-hint mt-4">Your order, rental and expense data is saved locally in this browser.</p></div></section></div>`;
}

const entityConfig = {
  farmers: { title:'Farmer records', subtitle:'Create, search and maintain farmer profiles across the village cluster.', collection:'farmers', add:'Add farmer', columns:['Farmer','Phone','Village','District','Status','Actions'], category:null, status:['Active','Inactive'], fields:[['name','Full name','text',true],['email','Email','email',true],['phone','Phone number','tel',true],['address','Address','text',false],['village','Village','text',true],['district','District','text',true],['state','State','text',true],['status','Status','select',true,['Active','Inactive']],['image','Profile image','image',false]] },
  crops: { title:'Crop library', subtitle:'Manage crop details and let farmers search by category, growing season and soil.', collection:'crops', add:'Add crop', columns:['Crop','Category','Season','Soil type','Status','Actions'], category:'category', status:['Active','Inactive'], fields:[['name','Crop name','text',true],['category','Category','select',true,['Cereal','Vegetable','Oilseed','Cash crop','Pulse','Other']],['season','Growing season','select',true,['Kharif','Rabi','Zaid','Annual']],['soil','Soil type','text',true],['water','Water requirement','select',true,['Low','Moderate','High']],['description','Description','textarea',false],['status','Status','select',true,['Active','Inactive']],['image','Crop image','image',false]] },
  equipment: { title:'Agricultural equipment', subtitle:'Keep machinery listings, rental pricing and availability up to date.', collection:'equipment', add:'Add equipment', columns:['Equipment','Category','Rental price','Unit','Availability','Actions'], category:'category', status:['Available','Booked','Rented','Maintenance'], fields:[['name','Equipment name','text',true],['category','Category','select',true,['Tractor','Harvester','Sowing','Sprayer','Tillage','Irrigation','Other']],['description','Description','textarea',false],['price','Rental price (₹)','number',true],['unit','Rental unit','select',true,['hour','day']],['status','Availability','select',true,['Available','Booked','Rented','Maintenance']],['image','Equipment image','image',false]] },
  products: { title:'Agricultural products', subtitle:'Manage farm supply listings, prices, categories and stock.', collection:'products', add:'Add product', columns:['Product','Category','Price','Stock','Status','Actions'], category:'category', status:['Active','Inactive'], fields:[['name','Product name','text',true],['category','Category','select',true,['Seeds','Fertilizers','Pesticides','Farming Tools','Irrigation Products','Other Agricultural Supplies']],['description','Description','textarea',false],['price','Price (₹)','number',true],['stock','Stock quantity','number',true],['status','Status','select',true,['Active','Inactive']],['image','Product image','image',false]] }
};

function queryParams() { return new URLSearchParams(window.location.search); }
function applyFilters(rows, config) {
  const params = queryParams(); const q = (params.get('q') || '').toLowerCase(); const category = params.get('category') || ''; const status = params.get('status') || ''; const sort = params.get('sort') || 'name-asc';
  let result = rows.filter((row) => {
    const searchable = [row.name,row.email,row.phone,row.village,row.district,row.category,row.description,row.season,row.soil].join(' ').toLowerCase();
    const min = params.get('min') === null || params.get('min') === '' ? null : Number(params.get('min'));
    const max = params.get('max') === null || params.get('max') === '' ? null : Number(params.get('max'));
    const season = params.get('season') || '';
    const district = params.get('district') || '';
    return (!q || searchable.includes(q)) && (!category || row[config.category] === category) && (!status || row.status === status) && (!season || row.season === season) && (!district || row.district === district) && (min === null || Number(row.price || 0) >= min) && (max === null || Number(row.price || 0) <= max);
  });
  result.sort((a,b) => {
    if (sort === 'name-desc') return String(b.name||'').localeCompare(String(a.name||''));
    if (sort === 'price-asc') return Number(a.price||0)-Number(b.price||0);
    if (sort === 'price-desc') return Number(b.price||0)-Number(a.price||0);
    if (sort === 'date-desc') return String(b.registeredAt||'').localeCompare(String(a.registeredAt||''));
    return String(a.name||'').localeCompare(String(b.name||''));
  });
  return result;
}
function filterBar(config) {
  const params = queryParams();
  const categories = config.category ? [...new Set(all(config.collection).map(x=>x[config.category]).filter(Boolean))] : [];
  const districts = config.collection==='farmers' ? [...new Set(all('farmers').map(x=>x.district).filter(Boolean))] : [];
  return `<form class="p2-filter-bar" id="filter-form"><label class="p2-filter-search"><span>⌕</span><input name="q" type="search" value="${e(params.get('q')||'')}" placeholder="Search by name or keyword"></label>${config.category ? `<select name="category" aria-label="Filter by category"><option value="">All categories</option>${categories.map(c=>`<option ${params.get('category')===c?'selected':''}>${e(c)}</option>`).join('')}</select>`:''}${config.collection==='crops'?`<select name="season" aria-label="Filter by season"><option value="">All seasons</option>${['Kharif','Rabi','Zaid','Annual'].map(s=>`<option ${params.get('season')===s?'selected':''}>${s}</option>`).join('')}</select>`:''}${districts.length?`<select name="district" aria-label="Filter by district"><option value="">All districts</option>${districts.map(d=>`<option ${params.get('district')===d?'selected':''}>${e(d)}</option>`).join('')}</select>`:''}<select name="status" aria-label="Filter by status"><option value="">All statuses</option>${config.status.map(s=>`<option ${params.get('status')===s?'selected':''}>${s}</option>`).join('')}</select>${config.collection==='equipment'||config.collection==='products'?`<input class="p2-price-input" name="min" type="number" min="0" value="${e(params.get('min')||'')}" placeholder="Min ₹" aria-label="Minimum price"><input class="p2-price-input" name="max" type="number" min="0" value="${e(params.get('max')||'')}" placeholder="Max ₹" aria-label="Maximum price">`:''}<select name="sort" aria-label="Sort records"><option value="name-asc" ${params.get('sort')==='name-asc'||!params.get('sort')?'selected':''}>Name: A to Z</option><option value="name-desc" ${params.get('sort')==='name-desc'?'selected':''}>Name: Z to A</option>${config.collection==='equipment'||config.collection==='products'?`<option value="price-asc" ${params.get('sort')==='price-asc'?'selected':''}>Price: low to high</option><option value="price-desc" ${params.get('sort')==='price-desc'?'selected':''}>Price: high to low</option>`:''}${config.collection==='farmers'?`<option value="date-desc" ${params.get('sort')==='date-desc'?'selected':''}>Newest first</option>`:''}</select><button class="btn btn-secondary btn-sm" type="submit">Apply</button><button class="btn btn-ghost btn-sm" type="button" data-action="reset-filters">Reset</button></form>`;
}

function actionButtons(entity, row) {
  return `<div class="p2-actions"><button class="btn btn-secondary btn-xs" type="button" data-action="edit-record" data-entity="${entity}" data-id="${row.id}">Edit</button><button class="btn btn-ghost btn-xs text-danger" type="button" data-action="delete-record" data-entity="${entity}" data-id="${row.id}">Delete</button></div>`;
}

function adminEntityTable(entity, rows, config) {
  return rows.map((row) => {
    if (entity === 'farmers') return `<tr><td><div class="p2-person"><img src="${safeImage(row.image)}" alt=""><span><strong>${e(row.name)}</strong><small>${e(row.email)}</small></span></div></td><td>${e(row.phone)}</td><td>${e(row.village)}</td><td>${e(row.district)}</td><td>${statusPill(row.status)}</td><td>${actionButtons(entity,row)}</td></tr>`;
    if (entity === 'crops') return `<tr><td><div class="p2-person"><img src="${safeImage(row.image)}" alt=""><span><strong>${e(row.name)}</strong><small>${e(row.water)} water need</small></span></div></td><td>${e(row.category)}</td><td>${e(row.season)}</td><td>${e(row.soil)}</td><td>${statusPill(row.status)}</td><td>${actionButtons(entity,row)}</td></tr>`;
    if (entity === 'equipment') return `<tr><td><div class="p2-person"><img src="${safeImage(row.image)}" alt=""><span><strong>${e(row.name)}</strong><small>${e(row.description || '')}</small></span></div></td><td>${e(row.category)}</td><td>${money(row.price)}</td><td>per ${e(row.unit)}</td><td>${statusPill(row.status)}</td><td>${actionButtons(entity,row)}</td></tr>`;
    return `<tr><td><div class="p2-person"><img src="${safeImage(row.image)}" alt=""><span><strong>${e(row.name)}</strong><small>${e(row.description || '')}</small></span></div></td><td>${e(row.category)}</td><td>${money(row.price)}</td><td>${Number(row.stock)}</td><td>${statusPill(row.status)}</td><td>${actionButtons(entity,row)}</td></tr>`;
  }).join('');
}

function productCards(rows, type='products') {
  if (!rows.length) return emptyState('No matching items','Try changing your search or filters.');
  return `<div class="p2-product-grid">${rows.map((row)=>`<article class="p2-product-card"><div class="p2-product-image"><img src="${safeImage(row.image)}" alt="${e(row.name)}"></div><div class="p2-product-body"><div class="p2-card-meta"><span>${e(row.category)}</span>${type==='products'?`<span>${Number(row.stock)} in stock</span>`:statusPill(row.status)}</div><h3>${e(row.name)}</h3><p>${e(row.description||'')}</p><div class="p2-card-bottom"><strong>${type==='products'?money(row.price):`${money(row.price)} / ${e(row.unit)}`}</strong>${type==='products'?`<button class="btn btn-primary btn-sm" data-action="cart-add" data-id="${row.id}" ${row.stock<1?'disabled':''}>Add to cart</button>`:`<button class="btn btn-primary btn-sm" data-action="request-rental" data-id="${row.id}" ${row.status==='Maintenance'?'disabled':''}>Request rental</button>`}</div></div></article>`).join('')}</div>`;
}

function entityPage(entity, user) {
  const config = entityConfig[entity];
  const admin = user.role === 'admin';
  const data = all(config.collection).filter(row => admin || (entity !== 'farmers' && row.status !== 'Inactive'));
  const rows = applyFilters(data, config);
  const actions = admin ? `<button class="btn btn-primary" type="button" data-action="open-form" data-entity="${entity}">＋ ${config.add}</button>` : '';
  let content;
  if (admin) {
    const body = adminEntityTable(entity, rows, config);
    content = `${filterBar(config)}${tableCard(`${config.title} (${rows.length})`,'Records saved in this browser',config.columns,body)}`;
  } else if (entity === 'products' || entity === 'equipment') {
    content = `${filterBar(config)}${productCards(rows, entity)}`;
  } else {
    content = `${filterBar(config)}<div class="p2-crop-grid">${rows.map((crop)=>`<article class="p2-crop-card"><img src="${safeImage(crop.image)}" alt="${e(crop.name)}"><div><span>${e(crop.category)} · ${e(crop.season)}</span><h3>${e(crop.name)}</h3><p>${e(crop.description)}</p><div class="p2-crop-facts"><span><small>Soil</small><strong>${e(crop.soil)}</strong></span><span><small>Water</small><strong>${e(crop.water)}</strong></span></div></div></article>`).join('') || emptyState('No crops found','Try a different crop name or category.')}</div>`;
  }
  if (entity==='farmers' && !admin) return `${pageHeader('My profile','View the information saved with your farmer account.')}${profilePage(user)}`;
  return `${pageHeader(config.title,config.subtitle,actions)}${content}`;
}

function profilePage(user) {
  const profile = farmerProfileFor(user);
  if (!profile) return emptyState('Profile not found','Your profile record is not available.');
  return `<section class="card p2-card"><div class="card__header"><h2 class="card__title">Personal information</h2><button class="btn btn-primary btn-sm" data-action="edit-profile" data-id="${profile.id}">Edit profile</button></div><div class="card__body"><div class="p2-profile"><img class="p2-profile-photo" src="${safeImage(profile.image)}" alt=""><div><h2>${e(profile.name)}</h2><p>${e(profile.email)}</p><small>${e(profile.phone)}</small></div></div><div class="p2-detail-grid mt-5">${[['Address',profile.address],['Village',profile.village],['District',profile.district],['State',profile.state],['Registered',shortDate(profile.registeredAt)],['Status',profile.status]].map(([k,v])=>`<div><small>${k}</small><strong>${e(v||'Not added')}</strong></div>`).join('')}</div></div></section>`;
}

function rentalPage(user) {
  const rentals = all('rentals'); const admin = user.role === 'admin';
  const profile = farmerProfileFor(user); const ownerId = profile?.id || user.farmerId || user.id;
  const params = queryParams(); const q = (params.get('q')||'').toLowerCase(); const state = params.get('status')||''; const from = params.get('from')||''; const to = params.get('to')||'';
  const rows = (admin ? rentals : rentals.filter(r=>r.farmerId===ownerId)).filter(r=>(!q||`${r.equipmentName} ${r.farmerName} ${r.id}`.toLowerCase().includes(q))&&(!state||r.status===state)&&(!from||r.startDate>=from)&&(!to||r.endDate<=to)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const filter = `<form class="p2-filter-bar" id="filter-form"><label class="p2-filter-search"><span>⌕</span><input name="q" type="search" value="${e(q)}" placeholder="Search equipment or farmer"></label><select name="status"><option value="">All statuses</option>${['Pending','Approved','Rejected','Active','Returned','Cancelled'].map(s=>`<option ${state===s?'selected':''}>${s}</option>`).join('')}</select><label class="p2-filter-date"><small>From</small><input name="from" type="date" value="${e(from)}"></label><label class="p2-filter-date"><small>To</small><input name="to" type="date" value="${e(to)}"></label><button class="btn btn-secondary btn-sm" type="submit">Apply</button><button class="btn btn-ghost btn-sm" type="button" data-action="reset-filters">Reset</button></form>`;
  const body = rows.map(r=>`<tr><td><strong>${e(r.equipmentName)}</strong><small class="p2-subcell">${e(r.id)}</small></td>${admin?`<td>${e(r.farmerName)}</td>`:''}<td>${shortDate(r.startDate)} – ${shortDate(r.endDate)}<small class="p2-subcell">${r.days} day(s)${r.unit==='hour'?` · ${r.hoursPerDay} hour(s)/day`:''}</small></td><td>${money(r.amount)}</td><td>${statusPill(r.status)}</td><td>${admin?`<div class="p2-actions">${r.status==='Pending'?`<button class="btn btn-primary btn-xs" data-action="rental-status" data-id="${r.id}" data-status="Approved">Approve</button><button class="btn btn-secondary btn-xs" data-action="rental-status" data-id="${r.id}" data-status="Rejected">Reject</button>`:''}${r.status==='Approved'?`<button class="btn btn-primary btn-xs" data-action="rental-status" data-id="${r.id}" data-status="Active">Mark active</button>`:''}${r.status==='Active'?`<button class="btn btn-secondary btn-xs" data-action="rental-status" data-id="${r.id}" data-status="Returned">Mark returned</button>`:''}</div>`:r.status==='Pending'?`<button class="btn btn-ghost btn-xs text-danger" data-action="rental-status" data-id="${r.id}" data-status="Cancelled">Cancel</button>`:'—'}</td></tr>`).join('');
  return `${pageHeader(admin?'Equipment rental requests':'My equipment rentals',admin?'Review requests, approve rental periods and track equipment returns.':'Track your rental requests and check their current status.',!admin?`<a href="equipment.html" class="btn btn-primary">Browse equipment</a>`:'')}${filter}${tableCard(admin?'All rental requests':'Rental history',`${rows.length} rental record(s)`,['Equipment',...(admin?['Farmer']:[]),'Rental period','Charge','Status','Action'],body)}`;
}

function cartPage(user) {
  const cart = getCart(user.id); const products = all('products');
  const items = cart.items.map((item)=>({ ...item, product: products.find(p=>p.id===item.productId) })).filter(x=>x.product);
  const total = items.reduce((s,x)=>s + Number(x.product.price)*Number(x.quantity),0);
  const rows = items.map((x)=>`<tr><td><div class="p2-person"><img src="${safeImage(x.product.image)}" alt=""><span><strong>${e(x.product.name)}</strong><small>${e(x.product.category)}</small></span></div></td><td>${money(x.product.price)}</td><td><div class="p2-quantity"><button data-action="cart-quantity" data-id="${x.product.id}" data-delta="-1" aria-label="Decrease quantity">−</button><strong>${x.quantity}</strong><button data-action="cart-quantity" data-id="${x.product.id}" data-delta="1" aria-label="Increase quantity">＋</button></div></td><td>${money(x.product.price*x.quantity)}</td><td><button class="btn btn-ghost btn-xs text-danger" data-action="cart-remove" data-id="${x.product.id}">Remove</button></td></tr>`).join('');
  return `${pageHeader('Shopping cart','Review your selected farm supplies before placing a demonstration order.',`<a href="products.html" class="btn btn-secondary">Continue shopping</a>`)}${items.length?`<div class="p2-cart-layout"><section class="card p2-card"><div class="card__body card__body--flush"><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div></section><section class="card p2-card p2-order-summary"><div class="card__header"><h2 class="card__title">Order summary</h2></div><div class="card__body"><div class="p2-summary-row"><span>Items</span><strong>${items.reduce((s,x)=>s+x.quantity,0)}</strong></div><div class="p2-summary-row"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="p2-summary-row"><span>Delivery</span><strong>Not included</strong></div><hr><div class="p2-summary-total"><span>Total</span><strong>${money(total)}</strong></div><button class="btn btn-primary btn-block mt-5" data-action="checkout">Place demonstration order</button><p class="form-hint mt-3">No payment is collected. Product stock is reduced after successful order placement.</p></div></section></div>`:emptyState('Your cart is empty','Browse agricultural products and add supplies to your cart.','<a class="btn btn-primary mt-4" href="products.html">Browse products</a>')}`;
}

function ordersPage(user) {
  const orders = all('orders'); const admin=user.role==='admin'; const profile=farmerProfileFor(user); const ownerId=profile?.id||user.farmerId||user.id;
  const params=queryParams(); const q=(params.get('q')||'').toLowerCase(); const state=params.get('status')||''; const from=params.get('from')||''; const to=params.get('to')||'';
  const rows = (admin?orders:orders.filter(o=>o.farmerId===ownerId)).filter(o=>(!q||`${o.id} ${o.farmerName} ${o.items.map(i=>i.name).join(' ')}`.toLowerCase().includes(q))&&(!state||o.status===state)&&(!from||o.createdAt.slice(0,10)>=from)&&(!to||o.createdAt.slice(0,10)<=to)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const filter=`<form class="p2-filter-bar" id="filter-form"><label class="p2-filter-search"><span>⌕</span><input name="q" type="search" value="${e(q)}" placeholder="Search order or product"></label><select name="status"><option value="">All statuses</option>${['Pending','Confirmed','Processing','Delivered','Cancelled'].map(s=>`<option ${state===s?'selected':''}>${s}</option>`).join('')}</select><label class="p2-filter-date"><small>From</small><input name="from" type="date" value="${e(from)}"></label><label class="p2-filter-date"><small>To</small><input name="to" type="date" value="${e(to)}"></label><button class="btn btn-secondary btn-sm" type="submit">Apply</button><button class="btn btn-ghost btn-sm" type="button" data-action="reset-filters">Reset</button></form>`;
  const body=rows.map(o=>`<tr><td><strong>${e(o.id)}</strong><small class="p2-subcell">${shortDate(o.createdAt)}</small></td>${admin?`<td>${e(o.farmerName)}</td>`:''}<td>${o.items.map(i=>`${e(i.name)} × ${i.quantity}`).join('<br>')}</td><td>${money(o.total)}</td><td>${statusPill(o.status)}</td><td>${admin?`<select class="p2-inline-select" data-order-status="${o.id}" aria-label="Update order status" ${['Delivered','Cancelled'].includes(o.status)?'disabled':''}><option ${o.status==='Pending'?'selected':''}>Pending</option>${['Confirmed','Processing','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select>`:o.status==='Pending'?`<button class="btn btn-ghost btn-xs text-danger" data-action="order-cancel" data-id="${o.id}">Cancel order</button>`:'—'}</td></tr>`).join('');
  const headers = admin ? ['Order','Farmer','Items','Total','Status','Update'] : ['Order','Items','Total','Status','Action'];
  return `${pageHeader(admin?'Product orders':'My orders',admin?'Review placed orders and update their fulfilment status.':'Track orders placed from the Kisan Mitra product catalogue.',!admin?`<a class="btn btn-primary" href="products.html">Shop products</a>`:'')}${filter}${tableCard(admin?'All orders':'Order history',`${rows.length} order(s)`,headers,body)}`;
}

function expensesPage(user) {
  const params=queryParams(); const expenseCategory=params.get('category')||''; const dateFrom=params.get('from')||''; const dateTo=params.get('to')||''; const expenses=expensesFor(user).filter(x=>(!expenseCategory||x.category===expenseCategory)&&(!dateFrom||x.date>=dateFrom)&&(!dateTo||x.date<=dateTo)).sort((a,b)=>b.date.localeCompare(a.date)); const total=expenseTotals(expenses);
  const allExpenses=expensesFor(user); const allTotal=expenseTotals(allExpenses);
  const income = Number(read('km_estimated_income_'+user.id,0)); const profit = income-allTotal;
  const body=expenses.map(x=>`<tr><td>${shortDate(x.date)}</td><td><strong>${e(x.category)}</strong><small class="p2-subcell">${e(x.description||'')}</small></td><td>${money(x.amount)}</td><td><div class="p2-actions"><button class="btn btn-secondary btn-xs" data-action="edit-record" data-entity="expenses" data-id="${x.id}">Edit</button><button class="btn btn-ghost btn-xs text-danger" data-action="delete-record" data-entity="expenses" data-id="${x.id}">Delete</button></div></td></tr>`).join('');
  return `${pageHeader('Agriculture expense calculator','Record farming costs, estimate income and calculate your expected profit or loss.',`<button class="btn btn-primary" data-action="open-form" data-entity="expenses">＋ Add expense</button>`)}<div class="grid grid--3 p2-stats">${statCard('Total expenses',money(allTotal),'Sum of all saved expense records','₹')}${statCard('Estimated income',money(income),'Your current income estimate','↗','stats-card__icon--secondary')}${statCard(profit>=0?'Estimated profit':'Estimated loss',money(Math.abs(profit)),profit>=0?'Income minus expenses':'Expenses are higher than income','∑','stats-card__icon--accent')}</div><section class="card p2-card mb-5"><div class="card__header"><h2 class="card__title">Income estimate</h2></div><div class="card__body"><form id="income-form" class="p2-income-form"><label class="form-group"><span class="form-label">Expected income (₹)</span><input class="form-control" type="number" min="0" step="0.01" name="income" value="${income}" required></label><button class="btn btn-secondary" type="submit">Save estimate</button></form></div></section>${`<form class="p2-filter-bar" id="filter-form"><label class="form-group p2-filter-inline"><span class="form-label">Category</span><select name="category" class="form-control"><option value="">All categories</option>${['Seeds','Fertilizers','Pesticides','Labour','Equipment Rental','Irrigation','Transportation','Other Expenses'].map(c=>`<option ${expenseCategory===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="form-group p2-filter-inline"><span class="form-label">From</span><input class="form-control" name="from" type="date" value="${e(dateFrom)}"></label><label class="form-group p2-filter-inline"><span class="form-label">To</span><input class="form-control" name="to" type="date" value="${e(dateTo)}"></label><button class="btn btn-secondary btn-sm" type="submit">Apply</button><button class="btn btn-ghost btn-sm" type="button" data-action="reset-filters">Reset</button></form>`}${tableCard('Expense history',`${expenses.length} matching record(s)`,['Date','Category / details','Amount','Actions'],body)}`;
}

function reportsPage() {
  const farmers=all('farmers'), crops=all('crops'), equip=all('equipment'), products=all('products'), orders=all('orders'), rentals=all('rentals'), expenses=all('expenses');
  const cropCounts=crops.reduce((acc,c)=>{acc[c.category]=(acc[c.category]||0)+1;return acc;},{});
  const max=Math.max(1,...Object.values(cropCounts));
  const bars=Object.entries(cropCounts).map(([name,count])=>`<div class="p2-bar-row"><span>${e(name)}</span><div><i style="width:${Math.round(count/max*100)}%"></i></div><strong>${count}</strong></div>`).join('')||emptyState('No crop data','Add crops to see the category breakdown.');
  const orderValue=orders.filter(o=>o.status!=='Cancelled').reduce((s,o)=>s+Number(o.total),0);
  return `${pageHeader('Reports & insights','Live summaries calculated from your saved farmer, crop, rental and order records.',`<button class="btn btn-secondary" data-action="export-report">Export CSV</button>`)}<div class="grid grid--4 p2-stats">${statCard('Farmers',farmers.length,'All profiles','♙')}${statCard('Crops',crops.length,'Crop records','♧')}${statCard('Equipment',equip.length,`${equip.filter(x=>x.status==='Available').length} available`,'⚙')}${statCard('Products',products.length,`${products.reduce((s,p)=>s+Number(p.stock||0),0)} stock units`,'▣')}</div><div class="grid grid--2 p2-dashboard-grid"><section class="card p2-card"><div class="card__header"><h2 class="card__title">Crop categories</h2><span class="text-small">Current library</span></div><div class="card__body">${bars}</div></section><section class="card p2-card"><div class="card__header"><h2 class="card__title">Order &amp; rental summary</h2></div><div class="card__body"><div class="p2-report-line"><span>Orders placed</span><strong>${orders.length}</strong></div><div class="p2-report-line"><span>Order value (excluding cancelled)</span><strong>${money(orderValue)}</strong></div><div class="p2-report-line"><span>Pending orders</span><strong>${orders.filter(o=>o.status==='Pending').length}</strong></div><div class="p2-report-line"><span>Delivered orders</span><strong>${orders.filter(o=>o.status==='Delivered').length}</strong></div><div class="p2-report-line"><span>Rental requests</span><strong>${rentals.length}</strong></div><div class="p2-report-line"><span>Pending rentals</span><strong>${rentals.filter(r=>r.status==='Pending').length}</strong></div><div class="p2-report-line"><span>Recorded expenses</span><strong>${money(expenses.reduce((s,x)=>s+Number(x.amount||0),0))}</strong></div></div></section></div>`;
}

function informationPage() {
  return `${pageHeader('Agriculture information','A quick reference area for crop planning and practical farm management.')}<div class="grid grid--2 p2-dashboard-grid"><section class="card p2-card"><div class="card__header"><h2 class="card__title">Seasonal crop planning</h2></div><div class="card__body"><div class="p2-info-item"><strong>Kharif</strong><p>Plan around monsoon onset. Rice and maize are common examples in the crop library.</p></div><div class="p2-info-item"><strong>Rabi</strong><p>Prepare for the winter season. Wheat, mustard and potato are examples available in this demo.</p></div><div class="p2-info-item"><strong>Zaid</strong><p>Plan short-duration summer crops according to water availability and local guidance.</p></div></div></section><section class="card p2-card"><div class="card__header"><h2 class="card__title">Good record-keeping practices</h2></div><div class="card__body"><ul class="p2-check-list"><li>Update crop, soil and water information before the season begins.</li><li>Confirm equipment rental dates before approving a request.</li><li>Review product stock before placing an order.</li><li>Record farm expenses regularly to keep estimates useful.</li><li>Keep a separate backup of important information.</li></ul></div></section></div><p class="p2-disclaimer">This section is general project information, not crop-specific agricultural or pesticide advice. Follow local agricultural extension guidance and product labels.</p>`;
}

function contactPage() {
  return `${pageHeader('Help & contact','Use this demo guide to understand the application and its LocalStorage limitations.')}<section class="card p2-card"><div class="card__body p2-help-content"><h2>How to use Kisan Mitra</h2><ol><li>Sign in with the Admin or Farmer demo account, or register a new Farmer account.</li><li>Use the sidebar to open each module available to your role.</li><li>Admins can add, edit and delete records. Farmers can browse crops, rent equipment and order products.</li><li>Use the theme button in the top bar to switch between light and dark mode.</li></ol><h2 class="mt-5">Demo storage and security</h2><p>All data is stored in this browser's LocalStorage. It is not shared between devices and can be removed if browser data is cleared. Authentication and role checks are demonstration-only and are not suitable for production deployment.</p><p>There is no online payment processing, email/SMS service or backend synchronization in Phase 2.</p></div></section>`;
}

export function renderContent(page, user) {
  switch (page) {
    case 'dashboard': return dashboard(user);
    case 'farmers': return entityPage('farmers',user);
    case 'crops': return entityPage('crops',user);
    case 'equipment': return entityPage('equipment',user);
    case 'products': return entityPage('products',user);
    case 'rental': return rentalPage(user);
    case 'cart': return cartPage(user);
    case 'orders': return ordersPage(user);
    case 'expenses': return expensesPage(user);
    case 'reports': return reportsPage();
    case 'information': return informationPage();
    case 'contact': return contactPage();
    default: return dashboard(user);
  }
}

